#!/usr/bin/env python3
from __future__ import annotations

import csv
import hashlib
from pathlib import Path
import sys


ROOT = Path(__file__).resolve().parents[1]
REPO = ROOT.parents[1]
MANIFEST = ROOT / "provenance" / "archive-manifest.csv"


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def main() -> int:
    failures: list[str] = []
    with MANIFEST.open(newline="") as handle:
        for row in csv.DictReader(handle):
            path = REPO / row["archive"]
            if not path.exists():
                failures.append(f"missing: {path}")
                continue
            expected_size = int(row["size_bytes"])
            actual_size = path.stat().st_size
            if actual_size != expected_size:
                failures.append(
                    f"size mismatch: {path} expected={expected_size} actual={actual_size}"
                )
                continue
            actual_sha = sha256(path)
            if actual_sha != row["sha256"]:
                failures.append(
                    f"sha256 mismatch: {path} expected={row['sha256']} actual={actual_sha}"
                )

    if failures:
        print("\n".join(failures))
        return 1

    print("All archives match archive-manifest.csv")
    return 0


if __name__ == "__main__":
    sys.exit(main())
